/**
 * How far back to reach for the level a series was left standing at. A level
 * can have been set however long before the window it is wanted for, so the
 * lookbacks widen until something turns up, rather than pulling every reading
 * a series ever held in one go.
 */
const LEVEL_LOOKBACKS_IN_MS = [
    36e5, // an hour
    864e5, // a day
    7 * 864e5, // a week
    31 * 864e5, // a month
    92 * 864e5, // a quarter
    460 * 864e5, // past the fifteen months CloudWatch keeps
];

/**
 * The newest reading a series holds before an instant, whenever it was
 * published, or nothing if the series was never read before then.
 */
export const readStandingUsageSample = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<UsageSample | undefined> => {
    for (const lookback of LEVEL_LOOKBACKS_IN_MS) {
        const samples = await readUsageSamples({
            series,
            startTime: new Date(before.getTime() - lookback),
            endTime: before,
        });
        if (samples.length) {
            return samples.reduce((standing, sample) =>
                new Date(sample.timestamp) > new Date(standing.timestamp) ? sample : standing,
            );
        }
    }
    return undefined;
};
