            const published = await listUsageSeries({ businessID, customerId, dimensionId });

            if (argumentAgg !== aggregationInterval.none) {
                const steps = stepsOfWindow({ startTime, endTime, interval: argumentAgg });
                // A provisioned dimension stands at a level rather than gathering
                // readings up, so a step without a reading of its own keeps the
                // level the last reading left it at.
                const provisioned = sampleType === SampleType.continious;
                const windowStart = new Date(startTime);
                const curveOfSeries = async (group: UsageSeries[]): Promise<UsageResponseDocument[]> => {
                    const samples: UsageSample[] = [];
                    for (const series of group) {
                        samples.push(...(await readUsageSamples({ series, startTime: windowStart, endTime: new Date(endTime) })));
                    }
                    let standingLevel: number;
                    if (provisioned) {
                        const standing: UsageSample[] = [];
                        for (const series of group) {
                            const sample = await readStandingUsageSample({ series, before: windowStart });
                            if (sample) {
                                standing.push(sample);
                            }
                        }
                        const [latest] = inTimeOrder(standing).slice(-1);
                        standingLevel = latest ? latest.value : undefined;
                    }
                    return curveOfSamples({
                        steps,
                        samples,
                        method: argumentAggregationMethod,
                        provisioned,
                        standingLevel,
                    });
                };

                // A dimension priced by metadata group is reported a group at a
                // time, every group it has published, rather than as one curve of
                // everything the dimension holds.
                if (tiersGroupByMetadata && tiersGroupByMetadata.length) {
                    const groups = published.reduce((acc, series) => {
                        const metadata = metadataOf(series);
                        const key = JSON.stringify(metadata);
                        if (!acc[key]) {
                            acc[key] = { metadata, series: [] };
                        }
                        acc[key].series.push(series);
                        return acc;
                    }, {} as Record<string, { metadata: Record<string, string>; series: UsageSeries[] }>);
                    const keys = Object.keys(groups).sort();
                    if (!keys.length) {
                        // Nothing published yet, so the dimension still gets its
                        // steps, empty ones.
                        return [{ usage: await curveOfSeries([]) }];
                    }
                    const curves: UsageCurve[] = [];
                    for (const key of keys) {
                        const { metadata, series } = groups[key];
                        const usage = await curveOfSeries(series);
                        curves.push(Object.keys(metadata).length ? { metadataGroup: metadata, usage } : { usage });
                    }
                    return curves;
                }

                return [{ usage: await curveOfSeries(published) }];
