import { UsageAggregationEvent } from './usageAggregation.event.js';
import { AggregatedUsageResponse, MetadataGroupedAggregatedUsageResponse } from '../customer/dto/read-customer.dto.js';
import { aggregationInterval, aggregationMethod, SampleType } from '../dimensions/dto/create-dimension.dto.js';

/**
 * The readings these specs read back are the ones the local usage metric store
 * holds for the business demo-labs: a dimension read a few times an hour, a
 * provisioned one whose level was set a fortnight earlier, one published under
 * two metadata groups, and one never read at all.
 */
const businessID = 'demo-labs';
const customerId = 'cus_sandbox01';
const offeringId = 'off_sandbox';

const scattered = {
    dimensionId: 'dim_widgets',
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    sampleType: SampleType.gauge,
};
const provisioned = {
    dimensionId: 'dim_licences',
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.max,
    sampleType: SampleType.continious,
};
const metadataPriced = {
    dimensionId: 'dim_egress_gb',
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    sampleType: SampleType.gauge,
    tiersGroupByMetadata: [
        {
            metadataGroups: { environment: 'production' },
            tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.01' }],
        },
    ],
};
const quiet = {
    dimensionId: 'dim_quiet',
    aggregationInterval: aggregationInterval.day,
    aggregationMethod: aggregationMethod.sum,
    sampleType: SampleType.gauge,
};

const usageOf = async (dimensions, startTime: string, endTime: string, forCustomer = customerId) =>
    (await UsageAggregationEvent.getAggregateUsageForDimension({
        businessID,
        customerId: forCustomer,
        clientID: forCustomer,
        startTime,
        endTime,
        offeringDocument: { offeringId, dimensions },
    } as never)) as (AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse)[];

describe('UsageAggregationEvent', () => {
    describe('getAggregateUsageForDimension', () => {
        it('hands back a step per aggregation interval, clock aligned and clamped to the window', async () => {
            const [widgets] = await usageOf([scattered], '2024-02-14T00:40:00Z', '2024-02-14T02:20:00Z');

            expect(widgets).toEqual({
                offeringId,
                dimensionId: 'dim_widgets',
                usage: [
                    {
                        value: '4',
                        startTime: '2024-02-14T00:40:00.000Z',
                        endTime: '2024-02-14T01:00:00.000Z',
                    },
                    {
                        value: '0',
                        startTime: '2024-02-14T01:00:00.000Z',
                        endTime: '2024-02-14T02:00:00.000Z',
                    },
                    {
                        value: '9',
                        startTime: '2024-02-14T02:00:00.000Z',
                        endTime: '2024-02-14T02:20:00.000Z',
                    },
                ],
            });
        });

        it('carries a provisioned level, set before the window, through steps with no reading', async () => {
            const [licences] = await usageOf([provisioned], '2024-02-14T00:40:00Z', '2024-02-14T02:20:00Z');

            expect(licences.usage.map(({ value }) => value)).toEqual(['2', '5', '5']);
        });

        it('stands a provisioned dimension at its level for a window with no reading in it at all', async () => {
            const [licences] = await usageOf([provisioned], '2024-02-10T00:00:00Z', '2024-02-10T03:00:00Z');

            expect(licences.usage.map(({ value }) => value)).toEqual(['2', '2', '2']);
        });

        it('reports every metadata group a metadata priced dimension published on its own', async () => {
            const groups = (await usageOf(
                [metadataPriced],
                '2024-02-14T00:40:00Z',
                '2024-02-14T02:20:00Z',
            )) as MetadataGroupedAggregatedUsageResponse[];

            expect(groups.length).toBe(2);
            expect(groups.map(({ metadataGroup }) => metadataGroup)).toEqual([
                { environment: 'production' },
                { environment: 'staging' },
            ]);
            expect(groups.map(({ usage }) => usage.map(({ value }) => value))).toEqual([
                ['3', '0', '1'],
                ['0', '9', '0'],
            ]);
            groups.forEach(({ dimensionId, offeringId: onOffering }) => {
                expect(dimensionId).toBe('dim_egress_gb');
                expect(onOffering).toBe(offeringId);
            });
        });

        it('hands back every step of a dimension the customer has no readings for', async () => {
            const [nothing] = await usageOf([quiet], '2024-02-12T00:00:00Z', '2024-02-14T12:00:00Z');

            expect(nothing).toEqual({
                offeringId,
                dimensionId: 'dim_quiet',
                usage: [
                    { value: '0', startTime: '2024-02-12T00:00:00.000Z', endTime: '2024-02-13T00:00:00.000Z' },
                    { value: '0', startTime: '2024-02-13T00:00:00.000Z', endTime: '2024-02-14T00:00:00.000Z' },
                    { value: '0', startTime: '2024-02-14T00:00:00.000Z', endTime: '2024-02-14T12:00:00.000Z' },
                ],
            });
        });

        it('hands back every step for a customer that has never been read', async () => {
            const [widgets] = await usageOf([scattered], '2024-02-14T00:00:00Z', '2024-02-14T03:00:00Z', 'cus_nobody');

            expect(widgets.usage.map(({ value }) => value)).toEqual(['0', '0', '0']);
        });

        it('aligns monthly steps to the month and clamps the ends to the window', async () => {
            const [widgets] = await usageOf(
                [{ ...scattered, aggregationInterval: aggregationInterval.month }],
                '2024-01-15T06:30:00Z',
                '2024-03-02T00:00:00Z',
            );

            expect(widgets.usage).toEqual([
                { value: '0', startTime: '2024-01-15T06:30:00.000Z', endTime: '2024-02-01T00:00:00.000Z' },
