                { value: '0', startTime: '2024-03-01T00:00:00.000Z', endTime: '2024-03-02T00:00:00.000Z' },
            ]);
        });

        it('leaves a window shorter than one step as a single clamped step', async () => {
            const [widgets] = await usageOf([scattered], '2024-02-14T00:44:00Z', '2024-02-14T00:51:00Z');

            expect(widgets.usage).toEqual([
                { value: '3', startTime: '2024-02-14T00:44:00.000Z', endTime: '2024-02-14T00:51:00.000Z' },
            ]);
        });

        it('still hands back the readings themselves when no interval is asked for', async () => {
            const [egress] = await usageOf(
                [{ ...metadataPriced, aggregationInterval: aggregationInterval.none }],
                '2024-02-14T00:00:00Z',
                '2024-02-14T03:00:00Z',
