const { usageData } = SupportedResources;

/** What a dimension's aggregation method makes of a set of readings. */
const reduceSamples = (values: number[], method: aggregationMethod): number => {
    if (values.length === 0) {
        return 0;
    }
    switch (method) {
        case aggregationMethod.max:
            return Math.max(...values);
        case aggregationMethod.min:
            return Math.min(...values);
        case aggregationMethod.average:
            return values.reduce((total, value) => total + value, 0) / values.length;
        case aggregationMethod.count:
            return values.length;
        case aggregationMethod.last:
            return values[values.length - 1];
        default:
            return values.reduce((total, value) => total + value, 0);
    }
};

/** One step of a curve, its edges already clamped to the window asked for. */
type UsageStep = { startTime: string; endTime: string; start: number; end: number };

/** One curve, of the dimension itself or of one metadata group it published. */
type UsageCurve = { metadataGroup?: Record<string, string>; usage: UsageResponseDocument[] };

/** The step a dimension asks for, or nothing if it wants the window whole. */
const stepLength = (interval: aggregationInterval): aggregationInterval | undefined => {
    const asked = aggregationInterval[`${interval}`.toLowerCase()];
    return asked === aggregationInterval.hour ||
        asked === aggregationInterval.day ||
        asked === aggregationInterval.month
        ? asked
        : undefined;
};

/** The instant the step holding an instant begins at, on the clock, in UTC. */
const stepEdgeAt = (instant: number, interval: aggregationInterval): number => {
    const at = new Date(instant);
    switch (interval) {
        case aggregationInterval.month:
            return Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), 1);
        case aggregationInterval.day:
            return Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate());
        default:
            return Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate(), at.getUTCHours());
    }
};

/** The clock aligned instant the step beginning at an edge gives way to. */
const stepEdgeAfter = (edge: number, interval: aggregationInterval): number => {
    const at = new Date(edge);
    switch (interval) {
        case aggregationInterval.month:
            return Date.UTC(at.getUTCFullYear(), at.getUTCMonth() + 1, 1);
        case aggregationInterval.day:
            return edge + 864e5;
        default:
            return edge + 36e5;
    }
};

/**
 * Every step a window covers in the length asked for, edges sitting on the
 * clock and the first and last one clamped to the window itself. A dimension
 * that asks for no step length is handed the whole window as one step.
 */
const stepsOfWindow = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: string;
    endTime: string;
    interval: aggregationInterval;
}): UsageStep[] => {
    const windowStart = new Date(startTime).getTime();
    const windowEnd = new Date(endTime).getTime();
    if (!(windowEnd > windowStart)) {
        return [];
    }
    const stepOf = (start: number, end: number): UsageStep => ({
        start,
        end,
        startTime: new Date(start).toISOString(),
        endTime: new Date(end).toISOString(),
    });
    const length = stepLength(interval);
    if (!length) {
        return [stepOf(windowStart, windowEnd)];
    }
    const steps: UsageStep[] = [];
    let edge = stepEdgeAt(windowStart, length);
    while (edge < windowEnd) {
        const next = stepEdgeAfter(edge, length);
        steps.push(stepOf(Math.max(edge, windowStart), Math.min(next, windowEnd)));
        edge = next;
    }
    return steps;
};

/** The readings a set of series holds, oldest first, however they arrived. */
const inTimeOrder = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((one, other) => new Date(one.timestamp).getTime() - new Date(other.timestamp).getTime());

/**
 * The curve a set of readings draws over a window's steps. A step with no
 * reading of its own is worth nothing, unless the dimension is provisioned, in
 * which case it stands at the level the last reading left it at, which may have
 * been set however long before the window began.
 */
const curveOfSamples = ({
    steps,
    samples,
    method,
    provisioned,
    standingLevel,
}: {
    steps: UsageStep[];
    samples: UsageSample[];
    method: aggregationMethod;
    provisioned?: boolean;
    standingLevel?: number;
}): UsageResponseDocument[] => {
    const ordered = inTimeOrder(samples);
    let level = standingLevel;
    let next = 0;
    return steps.map(({ start, end, startTime, endTime }) => {
        const readings: number[] = [];
        while (next < ordered.length && new Date(ordered[next].timestamp).getTime() < end) {
            const { timestamp, value } = ordered[next];
            if (new Date(timestamp).getTime() >= start) {
                readings.push(value);
            }
            next += 1;
        }
        let value = 0;
        if (readings.length) {
            value = reduceSamples(readings, method);
            level = readings[readings.length - 1];
        } else if (provisioned && level !== undefined) {
            value = level;
        }
        return new UsageDocument({ value: `${value}`, startTime, endTime });
    });
};
