                // A dimension priced by metadata group is reported a group at a
                // time, every group it has published, rather than as one curve of
                // everything the dimension holds.
                if (tiersGroupByMetadata && tiersGroupByMetadata.length) {
                    const groups = published.reduce(
                        (acc, series) => {
                            const metadata = metadataOf(series);
                            const key = JSON.stringify(metadata);
                            if (!acc[key]) {
                                acc[key] = { metadata, series: [] };
                            }
                            acc[key].series.push(series);
                            return acc;
                        },
                        {} as Record<string, { metadata: Record<string, string>; series: UsageSeries[] }>,
                    );
                    const keys = Object.keys(groups).sort();
                    if (!keys.length) {
                        // Nothing published yet, so the dimension still gets its
                        // steps, empty ones.
                        return [{ usage: await curveOfSeries([]) }];
                    }
                    const curves: UsageCurve[] = [];
                    for (const key of keys) {
                        const { metadata, series } = groups[key];
                        const usage = await curveOfSeries(series);
                        curves.push(Object.keys(metadata).length ? { metadataGroup: metadata, usage } : { usage });
                    }
                    return curves;
                }

                return [{ usage: await curveOfSeries(published) }];
            }

            const unAggregatedResults: BasicUsageDocument[] = [];
            for (const series of published) {
                const samples = await readUsageSamples({
                    series,
                    startTime: new Date(startTime),
                    endTime: new Date(endTime),
                });
                const metadata = metadataOf(series);
                samples.forEach(({ timestamp, value }) => {
                    unAggregatedResults.push({ timestamp, recordValue: value.toString(), metadata });
